// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime, uint256 balanceBefore, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(warpTime > 0);
        vm.assume(blockNum > 0);
        vm.assume(balanceBefore >= 10 ether);

        vm.deal(actor, balanceBefore);
        vm.deal(address(c), 0);

        vm.warp(warpTime);
        vm.roll(blockNum);

        uint256 initialPastTime = c.pastBlockTime();

        vm.prank(actor);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "first call must succeed");

        if (address(c).balance == 0) {
            return;
        }

        vm.prank(actor);
        (bool secondSuccess, ) = address(c).call{value: 10 ether}("");
        if (secondSuccess) {
            uint256 afterTime = c.pastBlockTime();
            assertTrue(afterTime > initialPastTime);
        }
    }
}
